#### Step 2: Instrument .NET Service (ASP.NET Core)

**Install NuGet Packages**:
```xml
<!-- Add to .csproj -->
<ItemGroup>
  <PackageReference Include="OpenTelemetry" Version="1.6.0" />
  <PackageReference Include="OpenTelemetry.Extensions.Hosting" Version="1.6.0" />
  <PackageReference Include="OpenTelemetry.Instrumentation.AspNetCore" Version="1.6.0-beta.2" />
  <PackageReference Include="OpenTelemetry.Instrumentation.Http" Version="1.6.0-beta.2" />
  <PackageReference Include="OpenTelemetry.Instrumentation.SqlClient" Version="1.6.0-beta.2" />
  <PackageReference Include="OpenTelemetry.Exporter.Jaeger" Version="1.5.1" />
  <PackageReference Include="OpenTelemetry.Exporter.OpenTelemetryProtocol" Version="1.6.0" />
</ItemGroup>
```

**Configure in Program.cs**:
```csharp
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

var builder = WebApplication.CreateBuilder(args);

// Configure OpenTelemetry
builder.Services.AddOpenTelemetry()
    .ConfigureResource(resource => resource
        .AddService(
            serviceName: "ClaimsIntakeService",
            serviceVersion: "1.0.0",
            serviceInstanceId: Environment.MachineName))
    .WithTracing(tracing => tracing
        // Automatic instrumentation for ASP.NET Core
        .AddAspNetCoreInstrumentation(options =>
        {
            options.RecordException = true;
            options.Filter = (httpContext) =>
            {
                // Exclude health check endpoints from tracing
                return !httpContext.Request.Path.StartsWithSegments("/health");
            };
            options.Enrich = (activity, eventName, rawObject) =>
            {
                // Add custom attributes
                if (rawObject is HttpRequest httpRequest)
                {
                    activity.SetTag("http.client_ip", httpRequest.HttpContext.Connection.RemoteIpAddress?.ToString());

                    // Add user context if authenticated
                    if (httpRequest.HttpContext.User.Identity?.IsAuthenticated == true)
                    {
                        activity.SetTag("user.id", httpRequest.HttpContext.User.FindFirst("sub")?.Value);
                        activity.SetTag("user.role", httpRequest.HttpContext.User.FindFirst("role")?.Value);
                    }
                }
            };
        })
        // Automatic instrumentation for HTTP client
        .AddHttpClientInstrumentation(options =>
        {
            options.RecordException = true;
            options.Enrich = (activity, eventName, rawObject) =>
            {
                if (rawObject is HttpResponseMessage response)
                {
                    activity.SetTag("http.response.size", response.Content.Headers.ContentLength);
                }
            };
        })
        // Automatic instrumentation for SQL Client
        .AddSqlClientInstrumentation(options =>
        {
            options.SetDbStatementForText = true;
            options.RecordException = true;
            options.Enrich = (activity, eventName, rawObject) =>
            {
                if (rawObject is System.Data.SqlClient.SqlCommand command)
                {
                    activity.SetTag("db.rows_affected", command.ExecuteNonQuery());
                }
            };
        })
        // Add custom instrumentation source
        .AddSource("ClaimsIntakeService")
        // Configure sampling
        .SetSampler(new TraceIdRatioBasedSampler(0.1)) // Sample 10%
        // Export to Jaeger
        .AddJaegerExporter(options =>
        {
            options.AgentHost = "jaeger-collector";
            options.AgentPort = 6831;
        })
        // Alternative: Export via OTLP (recommended for production)
        // .AddOtlpExporter(options =>
        // {
        //     options.Endpoint = new Uri("http://jaeger-collector:14250");
        //     options.Protocol = OtlpExportProtocol.Grpc;
        // })
    );

var app = builder.Build();

app.MapControllers();
app.Run();
```

**Create Manual Spans in Business Logic**:
```csharp
using System.Diagnostics;
using OpenTelemetry.Trace;

public class ClaimsService
{
    private static readonly ActivitySource ActivitySource = new("ClaimsIntakeService");
    private readonly HttpClient _httpClient;
    private readonly IDbConnection _dbConnection;

    public ClaimsService(HttpClient httpClient, IDbConnection dbConnection)
    {
        _httpClient = httpClient;
        _dbConnection = dbConnection;
    }

    public async Task<ClaimResult> ProcessClaimAsync(ClaimRequest request)
    {
        // Create custom span for business operation
        using var activity = ActivitySource.StartActivity("ProcessClaim", ActivityKind.Internal);

        // Add business context as tags
        activity?.SetTag("claim.id", request.ClaimId);
        activity?.SetTag("claim.type", request.ClaimType);
        activity?.SetTag("claim.amount", request.TotalAmount);
        activity?.SetTag("member.id", request.MemberId);
        activity?.SetTag("provider.id", request.ProviderId);

        try
        {
            // Step 1: Validate claim
            using (var validateActivity = ActivitySource.StartActivity("ValidateClaim", ActivityKind.Internal))
            {
                validateActivity?.SetTag("validation.rules", "eligibility,coverage,authorization");

                var validationResult = await ValidateClaimAsync(request);

                validateActivity?.SetTag("validation.result", validationResult.IsValid);

                if (!validationResult.IsValid)
                {
                    validateActivity?.SetStatus(ActivityStatusCode.Error, "Validation failed");
                    validateActivity?.SetTag("validation.errors", string.Join(",", validationResult.Errors));
                    throw new ValidationException(validationResult.Errors);
                }
            }

            // Step 2: Check eligibility (external service call)
            using (var eligibilityActivity = ActivitySource.StartActivity("CheckEligibility", ActivityKind.Client))
            {
                eligibilityActivity?.SetTag("service.name", "EligibilityService");

                var eligibilityResponse = await _httpClient.PostAsJsonAsync(
                    "http://eligibility-service/api/check",
                    new { MemberId = request.MemberId, ServiceDate = request.ServiceDate }
                );

                var eligibility = await eligibilityResponse.Content.ReadFromJsonAsync<EligibilityResult>();

                eligibilityActivity?.SetTag("eligibility.status", eligibility.Status);
                eligibilityActivity?.SetTag("eligibility.coverage_level", eligibility.CoverageLevel);
            }

            // Step 3: Save to database
            using (var dbActivity = ActivitySource.StartActivity("SaveClaim", ActivityKind.Internal))
            {
                dbActivity?.SetTag("db.operation", "INSERT");

                var claimId = await _dbConnection.ExecuteScalarAsync<int>(
                    "INSERT INTO Claims (MemberId, ProviderId, Amount, Status) VALUES (@MemberId, @ProviderId, @Amount, 'Submitted')",
                    new { request.MemberId, request.ProviderId, request.TotalAmount }
                );

                dbActivity?.SetTag("db.claim_id", claimId);
            }

            // Step 4: Calculate pricing (external service)
            using (var pricingActivity = ActivitySource.StartActivity("CalculatePricing", ActivityKind.Client))
            {
                pricingActivity?.SetTag("service.name", "PricingService");
                pricingActivity?.SetTag("pricing.procedure_codes", string.Join(",", request.ProcedureCodes));

                var pricingResponse = await _httpClient.PostAsJsonAsync(
                    "http://pricing-service/api/calculate",
                    new { ClaimId = request.ClaimId, ProcedureCodes = request.ProcedureCodes }
                );

                var pricing = await pricingResponse.Content.ReadFromJsonAsync<PricingResult>();

                pricingActivity?.SetTag("pricing.allowed_amount", pricing.AllowedAmount);
                pricingActivity?.SetTag("pricing.payment_amount", pricing.PaymentAmount);
            }

            activity?.SetStatus(ActivityStatusCode.Ok);
            activity?.SetTag("claim.result", "success");

            return new ClaimResult { Success = true, ClaimId = request.ClaimId };
        }
        catch (Exception ex)
        {
            // Record exception in span
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);

            throw;
        }
    }
}
```

