**Configure Programmatically (Alternative)**:
```java
import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.propagation.W3CTraceContextPropagator;
import io.opentelemetry.context.propagation.ContextPropagators;
import io.opentelemetry.exporter.otlp.trace.OtlpGrpcSpanExporter;
import io.opentelemetry.sdk.OpenTelemetrySdk;
import io.opentelemetry.sdk.resources.Resource;
import io.opentelemetry.sdk.trace.SdkTracerProvider;
import io.opentelemetry.sdk.trace.export.BatchSpanProcessor;
import io.opentelemetry.sdk.trace.samplers.Sampler;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class OpenTelemetryConfig {

    @Bean
    public OpenTelemetry openTelemetry() {
        Resource resource = Resource.getDefault()
            .merge(Resource.builder()
                .put("service.name", "eligibility-service")
                .put("service.version", "1.0.0")
                .put("deployment.environment", "production")
                .build());

        OtlpGrpcSpanExporter spanExporter = OtlpGrpcSpanExporter.builder()
            .setEndpoint("http://jaeger-collector:4317")
            .build();

        SdkTracerProvider tracerProvider = SdkTracerProvider.builder()
            .setResource(resource)
            .addSpanProcessor(BatchSpanProcessor.builder(spanExporter)
                .setMaxQueueSize(2048)
                .setMaxExportBatchSize(512)
                .setScheduleDelayMillis(5000)
                .build())
            .setSampler(Sampler.traceIdRatioBased(0.1))  // 10% sampling
            .build();

        return OpenTelemetrySdk.builder()
            .setTracerProvider(tracerProvider)
            .setPropagators(ContextPropagators.create(W3CTraceContextPropagator.getInstance()))
            .buildAndRegisterGlobal();
    }

    @Bean
    public Tracer tracer(OpenTelemetry openTelemetry) {
        return openTelemetry.getTracer("eligibility-service", "1.0.0");
    }
}
```

**Create Manual Spans in Service**:
```java
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.context.Scope;
import org.springframework.stereotype.Service;

@Service
public class EligibilityService {

    private final Tracer tracer;
    private final RestTemplate restTemplate;
    private final JdbcTemplate jdbcTemplate;

    public EligibilityService(Tracer tracer, RestTemplate restTemplate, JdbcTemplate jdbcTemplate) {
        this.tracer = tracer;
        this.restTemplate = restTemplate;
        this.jdbcTemplate = jdbcTemplate;
    }

    public EligibilityResult checkEligibility(String memberId, LocalDate serviceDate) {
        // Create custom span
        Span span = tracer.spanBuilder("CheckEligibility")
            .setSpanKind(SpanKind.INTERNAL)
            .startSpan();

        // Set span attributes
        span.setAttribute("member.id", memberId);
        span.setAttribute("service.date", serviceDate.toString());

        try (Scope scope = span.makeCurrent()) {
            // Step 1: Query member from database
            Span dbSpan = tracer.spanBuilder("QueryMember")
                .setSpanKind(SpanKind.CLIENT)
                .startSpan();

            try (Scope dbScope = dbSpan.makeCurrent()) {
                dbSpan.setAttribute("db.system", "postgresql");
                dbSpan.setAttribute("db.name", "members");
                dbSpan.setAttribute("db.operation", "SELECT");

                Member member = jdbcTemplate.queryForObject(
                    "SELECT * FROM members WHERE member_id = ?",
                    new Object[]{memberId},
                    (rs, rowNum) -> new Member(
                        rs.getString("member_id"),
                        rs.getString("status"),
                        rs.getString("plan_id")
                    )
                );

                dbSpan.setAttribute("db.rows", 1);
                dbSpan.setAttribute("member.status", member.getStatus());
                dbSpan.setStatus(StatusCode.OK);
            } catch (Exception e) {
                dbSpan.setStatus(StatusCode.ERROR, "Database query failed");
                dbSpan.recordException(e);
                throw e;
            } finally {
                dbSpan.end();
            }

            // Step 2: Check coverage with external service
            Span coverageSpan = tracer.spanBuilder("CheckCoverage")
                .setSpanKind(SpanKind.CLIENT)
                .startSpan();

            try (Scope coverageScope = coverageSpan.makeCurrent()) {
                coverageSpan.setAttribute("service.name", "CoverageService");
                coverageSpan.setAttribute("http.method", "POST");
                coverageSpan.setAttribute("http.url", "http://coverage-service/api/check");

                CoverageRequest coverageRequest = new CoverageRequest(memberId, serviceDate);
                CoverageResult coverage = restTemplate.postForObject(
                    "http://coverage-service/api/check",
                    coverageRequest,
                    CoverageResult.class
                );

                coverageSpan.setAttribute("coverage.level", coverage.getCoverageLevel());
                coverageSpan.setAttribute("coverage.active", coverage.isActive());
                coverageSpan.setStatus(StatusCode.OK);
            } catch (Exception e) {
                coverageSpan.setStatus(StatusCode.ERROR, "Coverage check failed");
                coverageSpan.recordException(e);
                throw e;
            } finally {
                coverageSpan.end();
            }

            // Step 3: Business logic - determine eligibility
            Span businessSpan = tracer.spanBuilder("DetermineEligibility")
                .setSpanKind(SpanKind.INTERNAL)
                .startSpan();

            try (Scope businessScope = businessSpan.makeCurrent()) {
                boolean isEligible = determineEligibility(member, coverage);

                businessSpan.setAttribute("eligibility.result", isEligible);
                businessSpan.setAttribute("eligibility.reason", isEligible ? "Active coverage" : "Coverage inactive");
                businessSpan.setStatus(StatusCode.OK);

                span.setAttribute("result.eligible", isEligible);
                span.setStatus(StatusCode.OK);

                return new EligibilityResult(memberId, isEligible);
            } finally {
                businessSpan.end();
            }

        } catch (Exception e) {
            span.setStatus(StatusCode.ERROR, e.getMessage());
            span.recordException(e);
            throw new EligibilityException("Eligibility check failed", e);
        } finally {
            span.end();
        }
    }
}
```

