#### Step 4: Instrument Node.js Service (Express)

**Install NPM Packages**:
```bash
npm install @opentelemetry/api \
  @opentelemetry/sdk-node \
  @opentelemetry/auto-instrumentations-node \
  @opentelemetry/exporter-trace-otlp-grpc \
  @opentelemetry/resources \
  @opentelemetry/semantic-conventions
```

**Create Tracing Configuration (tracing.js)**:
```javascript
const { NodeSDK } = require('@opentelemetry/sdk-node');
const { getNodeAutoInstrumentations } = require('@opentelemetry/auto-instrumentations-node');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-trace-otlp-grpc');
const { Resource } = require('@opentelemetry/resources');
const { SemanticResourceAttributes } = require('@opentelemetry/semantic-conventions');
const { TraceIdRatioBasedSampler } = require('@opentelemetry/sdk-trace-base');

const resource = new Resource({
  [SemanticResourceAttributes.SERVICE_NAME]: 'pricing-service',
  [SemanticResourceAttributes.SERVICE_VERSION]: '1.0.0',
  [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: 'production',
});

const traceExporter = new OTLPTraceExporter({
  url: 'http://jaeger-collector:4317',
});

const sdk = new NodeSDK({
  resource: resource,
  traceExporter: traceExporter,
  instrumentations: [
    getNodeAutoInstrumentations({
      // Automatic instrumentation for HTTP, Express, MongoDB, PostgreSQL, etc.
      '@opentelemetry/instrumentation-http': {
        ignoreIncomingPaths: ['/health', '/metrics'],
        requestHook: (span, request) => {
          span.setAttribute('http.client_ip', request.socket.remoteAddress);
        },
      },
      '@opentelemetry/instrumentation-express': {
        requestHook: (span, info) => {
          span.setAttribute('express.route', info.route);
        },
      },
      '@opentelemetry/instrumentation-pg': {
        enhancedDatabaseReporting: true,
      },
    }),
  ],
  sampler: new TraceIdRatioBasedSampler(0.1), // 10% sampling
});

sdk.start();

// Graceful shutdown
process.on('SIGTERM', () => {
  sdk.shutdown()
    .then(() => console.log('Tracing terminated'))
    .catch((error) => console.log('Error terminating tracing', error))
    .finally(() => process.exit(0));
});

module.exports = sdk;
```

**Initialize Tracing Before Application (server.js)**:
```javascript
// IMPORTANT: Import tracing BEFORE any other imports
require('./tracing');

const express = require('express');
const { trace, context, SpanStatusCode } = require('@opentelemetry/api');

const app = express();
app.use(express.json());

// Get tracer for manual instrumentation
const tracer = trace.getTracer('pricing-service', '1.0.0');

// Example endpoint with manual spans
app.post('/api/calculate', async (req, res) => {
  const { claimId, procedureCodes } = req.body;

  // Create custom span for business operation
  const span = tracer.startSpan('CalculatePricing', {
    kind: SpanKind.INTERNAL,
    attributes: {
      'claim.id': claimId,
      'pricing.procedure_codes': procedureCodes.join(','),
      'pricing.procedure_count': procedureCodes.length,
    },
  });

  // Run operation within span context
  const ctx = trace.setSpan(context.active(), span);

  try {
    // Step 1: Fetch fee schedule from database
    const feeScheduleSpan = tracer.startSpan('FetchFeeSchedule', {
      parent: span,
      kind: SpanKind.CLIENT,
      attributes: {
        'db.system': 'postgresql',
        'db.name': 'pricing',
        'db.operation': 'SELECT',
      },
    }, ctx);

    const feeSchedule = await context.with(trace.setSpan(ctx, feeScheduleSpan), async () => {
      const result = await db.query(
        [procedureCodes]
      );
      feeScheduleSpan.setAttribute('db.rows', result.rows.length);
      return result.rows;
    });

    feeScheduleSpan.setStatus({ code: SpanStatusCode.OK });
    feeScheduleSpan.end();

    // Step 2: Apply pricing rules
    const rulesSpan = tracer.startSpan('ApplyPricingRules', {
      parent: span,
      kind: SpanKind.INTERNAL,
      attributes: {
        'pricing.rules': 'contractual_adjustment,provider_discount',
      },
    }, ctx);

    const pricing = await context.with(trace.setSpan(ctx, rulesSpan), async () => {
      const result = applyPricingRules(feeSchedule, procedureCodes);
      rulesSpan.setAttribute('pricing.allowed_amount', result.allowedAmount);
      rulesSpan.setAttribute('pricing.adjustment_amount', result.adjustmentAmount);
      return result;
    });

    rulesSpan.setStatus({ code: SpanStatusCode.OK });
    rulesSpan.end();

    // Step 3: Call external pricer API
    const externalSpan = tracer.startSpan('CallExternalPricer', {
      parent: span,
      kind: SpanKind.CLIENT,
      attributes: {
        'service.name': 'ExternalPricerAPI',
        'http.method': 'POST',
        'http.url': 'https://external-pricer.com/api/price',
      },
    }, ctx);

    const externalPricing = await context.with(trace.setSpan(ctx, externalSpan), async () => {
      const response = await fetch('https://external-pricer.com/api/price', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ procedureCodes, allowedAmount: pricing.allowedAmount }),
      });

      externalSpan.setAttribute('http.status_code', response.status);
      externalSpan.setAttribute('http.response_size', response.headers.get('content-length'));

      return await response.json();
    });

    externalSpan.setStatus({ code: SpanStatusCode.OK });
    externalSpan.end();

    // Final calculation
    const paymentAmount = pricing.allowedAmount - externalPricing.contractualAdjustment;

    span.setAttribute('pricing.payment_amount', paymentAmount);
    span.setAttribute('result', 'success');
    span.setStatus({ code: SpanStatusCode.OK });

    res.json({
      claimId,
      allowedAmount: pricing.allowedAmount,
      paymentAmount: paymentAmount,
      adjustments: externalPricing.adjustments,
    });

  } catch (error) {
    span.setStatus({
      code: SpanStatusCode.ERROR,
      message: error.message,
    });
    span.recordException(error);

    res.status(500).json({ error: 'Pricing calculation failed' });
  } finally {
    span.end();
  }
});

app.listen(3000, () => {
  console.log('Pricing service listening on port 3000');
});
```

