#### Step 5: Propagate Trace Context in Azure Service Bus

**Producer (Publishing Message with Trace Context)**:
```csharp
using Azure.Messaging.ServiceBus;
using OpenTelemetry;
using OpenTelemetry.Context.Propagation;
using System.Diagnostics;

public class ClaimPublisher
{
    private static readonly ActivitySource ActivitySource = new("ClaimsIntakeService");
    private static readonly TextMapPropagator Propagator = Propagators.DefaultTextMapPropagator;

    private readonly ServiceBusClient _serviceBusClient;
    private readonly ServiceBusSender _sender;

    public ClaimPublisher(ServiceBusClient serviceBusClient)
    {
        _serviceBusClient = serviceBusClient;
        _sender = _serviceBusClient.CreateSender("claims-queue");
    }

    public async Task PublishClaimAsync(Claim claim)
    {
        using var activity = ActivitySource.StartActivity("PublishClaim", ActivityKind.Producer);

        activity?.SetTag("messaging.system", "azure-service-bus");
        activity?.SetTag("messaging.destination", "claims-queue");
        activity?.SetTag("messaging.destination_kind", "queue");
        activity?.SetTag("claim.id", claim.ClaimId);

        var message = new ServiceBusMessage(JsonSerializer.Serialize(claim))
        {
            MessageId = Guid.NewGuid().ToString(),
            ContentType = "application/json",
        };

        // Inject trace context into message properties
        Propagator.Inject(new PropagationContext(activity?.Context ?? default, Baggage.Current), message.ApplicationProperties, InjectTraceContext);

        await _sender.SendMessageAsync(message);

        activity?.SetTag("messaging.message_id", message.MessageId);
    }

    private void InjectTraceContext(IDictionary<string, object> props, string key, string value)
    {
        props[key] = value;
    }
}
```

**Consumer (Extracting Trace Context)**:
```csharp
public class ClaimProcessor
{
    private static readonly ActivitySource ActivitySource = new("ClaimsProcessingService");
    private static readonly TextMapPropagator Propagator = Propagators.DefaultTextMapPropagator;

    private readonly ServiceBusProcessor _processor;

    public ClaimProcessor(ServiceBusClient serviceBusClient)
    {
        _processor = serviceBusClient.CreateProcessor("claims-queue");
        _processor.ProcessMessageAsync += ProcessMessageAsync;
        _processor.ProcessErrorAsync += ProcessErrorAsync;
    }

    private async Task ProcessMessageAsync(ProcessMessageEventArgs args)
    {
        // Extract trace context from message properties
        var parentContext = Propagator.Extract(default, args.Message.ApplicationProperties, ExtractTraceContext);
        Baggage.Current = parentContext.Baggage;

        // Create span linked to producer's span
        using var activity = ActivitySource.StartActivity(
            "ProcessClaim",
            ActivityKind.Consumer,
            parentContext.ActivityContext);

        activity?.SetTag("messaging.system", "azure-service-bus");
        activity?.SetTag("messaging.source", "claims-queue");
        activity?.SetTag("messaging.message_id", args.Message.MessageId);
        activity?.SetTag("messaging.operation", "process");

        try
        {
            var claim = JsonSerializer.Deserialize<Claim>(args.Message.Body.ToString());

            activity?.SetTag("claim.id", claim.ClaimId);
            activity?.SetTag("claim.amount", claim.TotalAmount);

            // Process claim (child spans created here will be linked to this span)
            await ProcessClaimLogicAsync(claim);

            await args.CompleteMessageAsync(args.Message);

            activity?.SetStatus(ActivityStatusCode.Ok);
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);

            await args.AbandonMessageAsync(args.Message);
        }
    }

    private IEnumerable<string> ExtractTraceContext(IDictionary<string, object> props, string key)
    {
        if (props.TryGetValue(key, out var value))
        {
            return new[] { value.ToString() };
        }
        return Enumerable.Empty<string>();
    }
}
